    stopVisemeAnim();
    clearViseme();
    tts.playing = false;
    tts.audio = null;
    tts.current = null;
    if (tts.watchdog) { clearTimeout(tts.watchdog); tts.watchdog = null; }
    if (State.mode === 'speaking') State.mode = 'idle';
